package stanhebben.zenscript;
import java.nio.file.Files;
import java.nio.file.Path;
import stanhebben.zenscript.ZenModule;
import stanhebben.zenscript.impl.GenericCompileEnvironment;
import stanhebben.zenscript.impl.GenericRegistry;
import stanhebben.zenscript.TestErrorLogger;
public class ZenCheck {
    public static void println(String value) { System.out.println(value); }

    public static void main(String[] args) throws Exception {
        var environment = new GenericCompileEnvironment();
        var logger = new TestErrorLogger();
        var registry = new GenericRegistry(environment, logger);
        registry.registerGlobal("println", registry.getStaticFunction(ZenCheck.class, "println", String.class));
        registry.registerGlobal("root", registry.getRoot());
        var source = Path.of(args[0]);
        var module = ZenModule.compileScriptString(Files.readString(source), source.getFileName().toString(), environment, ZenCheck.class.getClassLoader());
        var execute = module.getMain();
        if (execute == null || !logger.listError.isEmpty()) {
            throw new IllegalStateException("Could not compile the module: " + logger.listError);
        }
        execute.run();
    }
}
